using System.Security.Claims;
using Microsoft.Data.Sqlite;

public static class AdvancedEndpoints
{
    static string U(ClaimsPrincipal u)=>u.FindFirstValue(ClaimTypes.NameIdentifier)!;
    static string R(ClaimsPrincipal u)=>u.FindFirstValue(ClaimTypes.Role)??"";
    static bool Has(ClaimsPrincipal u,params string[] roles)=>roles.Contains(R(u));
    public static void MapAdvancedEndpoints(this WebApplication app)
    {
        app.MapGet("/api/toppings",async(Guid? productId)=>{await using var c=DemoDb.Open();var rs=await DemoDb.Rows(c,"SELECT Id,ProductId,Name,Price,IsActive FROM ProductToppings WHERE IsActive=1"+(productId.HasValue?" AND ProductId=@p":"")+" ORDER BY Name",("@p",productId));return Results.Ok(rs.Select(r=>new{id=r.G("Id"),productId=r.G("ProductId"),name=r.S("Name"),price=r.I("Price"),isActive=r.B("IsActive")}));});
        app.MapPost("/api/toppings",async(ToppingInput x,ClaimsPrincipal u)=>{if(!Has(u,"owner","manager"))return Results.Json(new{error="Chỉ quản lý được thêm topping."},statusCode:403);if(string.IsNullOrWhiteSpace(x.Name)||x.Price<0)return Results.BadRequest(new{error="Topping không hợp lệ."});await using var c=DemoDb.Open();var id=DemoDb.Id();try{await DemoDb.Exec(c,"INSERT INTO ProductToppings(Id,ProductId,Name,Price)VALUES(@id,@p,@n,@v)",( "@id",id),("@p",x.ProductId),("@n",x.Name.Trim()),("@v",x.Price));return Results.Ok(new{id=Guid.Parse(id)});}catch(SqliteException){return Results.Conflict(new{error="Topping đã tồn tại cho món này."});}});
        app.MapDelete("/api/toppings/{id:guid}",async(Guid id,ClaimsPrincipal u)=>{if(!Has(u,"owner","manager"))return Results.Json(new{error="Không có quyền."},statusCode:403);await using var c=DemoDb.Open();return await DemoDb.Exec(c,"UPDATE ProductToppings SET IsActive=0 WHERE Id=@id",("@id",id))>0?Results.NoContent():Results.NotFound();});

        app.MapGet("/api/areas",async()=>{await using var c=DemoDb.Open();var rs=await DemoDb.Rows(c,"SELECT a.Id,a.Name,a.Position,a.CanvasWidth,a.CanvasHeight,COUNT(t.Id) TableCount FROM Areas a LEFT JOIN DiningTables t ON t.AreaId=a.Id GROUP BY a.Id ORDER BY a.Position,a.Name");return Results.Ok(rs.Select(r=>new{id=r.G("Id"),name=r.S("Name"),position=r.I("Position"),canvasWidth=r.I("CanvasWidth"),canvasHeight=r.I("CanvasHeight"),tableCount=r.I("TableCount")}));});
        app.MapPost("/api/areas",async(AreaInput x,ClaimsPrincipal u)=>{if(!Has(u,"owner","manager"))return Results.Json(new{error="Chỉ quản lý được thêm khu vực."},statusCode:403);if(string.IsNullOrWhiteSpace(x.Name))return Results.BadRequest(new{error="Tên khu vực không được để trống."});await using var c=DemoDb.Open();var id=DemoDb.Id();await DemoDb.Exec(c,"INSERT INTO Areas(Id,StoreId,Name,Position,CanvasWidth,CanvasHeight)VALUES(@id,(SELECT Id FROM Stores LIMIT 1),@n,(SELECT COALESCE(MAX(Position),0)+1 FROM Areas),@w,@h)",( "@id",id),("@n",x.Name.Trim()),("@w",Math.Clamp(x.CanvasWidth,500,2400)),("@h",Math.Clamp(x.CanvasHeight,400,1600)));return Results.Ok(new{id=Guid.Parse(id)});});
        app.MapPatch("/api/areas/{id:guid}",async(Guid id,AreaInput x,ClaimsPrincipal u)=>{if(!Has(u,"owner","manager"))return Results.Json(new{error="Chỉ quản lý được sửa khu vực."},statusCode:403);await using var c=DemoDb.Open();return await DemoDb.Exec(c,"UPDATE Areas SET Name=@n,CanvasWidth=@w,CanvasHeight=@h WHERE Id=@id",("@n",x.Name.Trim()),("@w",Math.Clamp(x.CanvasWidth,500,2400)),("@h",Math.Clamp(x.CanvasHeight,400,1600)),("@id",id))>0?Results.Ok(new{id}):Results.NotFound();});
        app.MapDelete("/api/areas/{id:guid}",async(Guid id,ClaimsPrincipal u)=>{if(!Has(u,"owner","manager"))return Results.Json(new{error="Chỉ quản lý được xóa khu vực."},statusCode:403);await using var c=DemoDb.Open();if(await DemoDb.ScalarLong(c,"SELECT COUNT(*) FROM DiningTables WHERE AreaId=@id",("@id",id))>0)return Results.Conflict(new{error="Hãy chuyển hoặc xóa hết bàn trong khu vực trước."});if(await DemoDb.ScalarLong(c,"SELECT COUNT(*) FROM Areas")<=1)return Results.Conflict(new{error="Quán phải còn ít nhất một khu vực."});return await DemoDb.Exec(c,"DELETE FROM Areas WHERE Id=@id",("@id",id))>0?Results.NoContent():Results.NotFound();});
        app.MapPatch("/api/tables/{id:guid}/position",async(Guid id,TablePositionInput x,ClaimsPrincipal u)=>{if(!Has(u,"owner","manager"))return Results.Json(new{error="Chỉ quản lý được sửa sơ đồ bàn."},statusCode:403);await using var c=DemoDb.Open();return await DemoDb.Exec(c,"UPDATE DiningTables SET PositionX=@x,PositionY=@y WHERE Id=@id",("@x",Math.Max(0,x.X)),("@y",Math.Max(0,x.Y)),("@id",id))>0?Results.Ok(new{id,x=x.X,y=x.Y}):Results.NotFound();});
        app.MapPatch("/api/tables/{id:guid}/layout",async(Guid id,TableLayoutInput x,ClaimsPrincipal u)=>{if(!Has(u,"owner","manager"))return Results.Json(new{error="Chỉ quản lý được sửa sơ đồ bàn."},statusCode:403);if(!new[]{"rectangle","round","square"}.Contains(x.Shape))return Results.BadRequest(new{error="Kiểu bàn không hợp lệ."});await using var c=DemoDb.Open();return await DemoDb.Exec(c,"UPDATE DiningTables SET AreaId=@a,PositionX=@x,PositionY=@y,Width=@w,Height=@h,Shape=@s WHERE Id=@id",("@a",x.AreaId),("@x",Math.Max(0,x.X)),("@y",Math.Max(0,x.Y)),("@w",Math.Clamp(x.Width,90,360)),("@h",Math.Clamp(x.Height,80,260)),("@s",x.Shape),("@id",id))>0?Results.Ok(new{id}):Results.NotFound();});
        app.MapPost("/api/tables/transfer",async(TableTransferInput x,ClaimsPrincipal u)=>{if(!Has(u,"owner","manager","server"))return Results.Json(new{error="Không có quyền đổi bàn."},statusCode:403);await using var c=DemoDb.Open();using var tx=c.BeginTransaction();var source=(await DemoDb.Rows(c,tx,"SELECT TableId FROM Orders WHERE Id=@o AND Status NOT IN ('paid','cancelled')",("@o",x.OrderId))).FirstOrDefault();if(source is null){tx.Rollback();return Results.NotFound(new{error="Đơn nguồn không tồn tại."});}var target=(await DemoDb.Rows(c,tx,"SELECT Id FROM Orders WHERE TableId=@t AND Status NOT IN ('paid','cancelled') ORDER BY OpenedAt DESC LIMIT 1",("@t",x.TargetTableId))).FirstOrDefault();if(target is not null&&!x.Merge){tx.Rollback();return Results.Conflict(new{error="Bàn đích đang có khách. Hãy chọn gộp bàn."});}string resultOrder;if(target is not null){resultOrder=target.S("Id");await DemoDb.Exec(c,tx,"UPDATE OrderItems SET OrderId=@target WHERE OrderId=@source;UPDATE Orders SET Subtotal=Subtotal+(SELECT Subtotal FROM Orders WHERE Id=@source),Total=Total+(SELECT Total FROM Orders WHERE Id=@source),Status='sent' WHERE Id=@target;UPDATE Orders SET Status='cancelled',ClosedAt=@now,Note=COALESCE(Note,'')||' [Đã gộp vào đơn khác]' WHERE Id=@source",("@target",resultOrder),("@source",x.OrderId),("@now",DemoDb.Now));}else{resultOrder=x.OrderId.ToString();await DemoDb.Exec(c,tx,"UPDATE Orders SET TableId=@target WHERE Id=@order",("@target",x.TargetTableId),("@order",x.OrderId));}await DemoDb.Exec(c,tx,"UPDATE DiningTables SET Status='available' WHERE Id=@source;UPDATE DiningTables SET Status='occupied' WHERE Id=@target",("@source",source.S("TableId")),("@target",x.TargetTableId));tx.Commit();return Results.Ok(new{orderId=Guid.Parse(resultOrder),targetTableId=x.TargetTableId,merged=target is not null});});

        app.MapGet("/api/customers",async(string? phone)=>{await using var c=DemoDb.Open();var rs=await DemoDb.Rows(c,"SELECT Id,FullName,Phone,Points,TotalSpent,CreatedAt FROM Customers WHERE @p='' OR Phone LIKE @p||'%' ORDER BY TotalSpent DESC LIMIT 30",("@p",phone?.Trim()??""));return Results.Ok(rs.Select(r=>new{id=r.G("Id"),name=r.S("FullName"),phone=r.S("Phone"),points=r.I("Points"),totalSpent=r.L("TotalSpent"),createdAt=r.D("CreatedAt")}));});
        app.MapPost("/api/customers",async(CustomerInput x)=>{if(string.IsNullOrWhiteSpace(x.Phone)||string.IsNullOrWhiteSpace(x.Name))return Results.BadRequest(new{error="Nhập tên và số điện thoại."});await using var c=DemoDb.Open();var existing=(await DemoDb.Rows(c,"SELECT Id FROM Customers WHERE Phone=@p LIMIT 1",("@p",x.Phone.Trim()))).FirstOrDefault();var id=existing?.S("Id")??DemoDb.Id();if(existing is null)await DemoDb.Exec(c,"INSERT INTO Customers(Id,StoreId,Phone,FullName,CreatedAt)VALUES(@id,(SELECT Id FROM Stores LIMIT 1),@p,@n,@now)",( "@id",id),("@p",x.Phone.Trim()),("@n",x.Name.Trim()),("@now",DemoDb.Now));else await DemoDb.Exec(c,"UPDATE Customers SET FullName=@n WHERE Id=@id",("@n",x.Name.Trim()),("@id",id));var r=(await DemoDb.Rows(c,"SELECT Id,FullName,Phone,Points FROM Customers WHERE Id=@id",("@id",id))).First();return Results.Ok(new{id=r.G("Id"),name=r.S("FullName"),phone=r.S("Phone"),points=r.I("Points")});});
        app.MapPost("/api/orders/{id:guid}/customer",async(Guid id,OrderCustomerInput x)=>{await using var c=DemoDb.Open();return await DemoDb.Exec(c,"UPDATE Orders SET CustomerId=@c WHERE Id=@id AND Status NOT IN ('paid','cancelled')",("@c",x.CustomerId),("@id",id))>0?Results.Ok(new{id,customerId=x.CustomerId}):Results.NotFound();});
        app.MapPost("/api/orders/{id:guid}/redeem-points",async(Guid id,RedeemPointsInput x)=>{if(x.Points<=0)return Results.BadRequest(new{error="Số điểm phải lớn hơn 0."});await using var c=DemoDb.Open();using var tx=c.BeginTransaction();var r=(await DemoDb.Rows(c,tx,"SELECT o.CustomerId,o.Subtotal,o.Discount,o.PointsRedeemed,c.Points FROM Orders o LEFT JOIN Customers c ON c.Id=o.CustomerId WHERE o.Id=@id AND o.Status NOT IN ('paid','cancelled')",("@id",id))).FirstOrDefault();if(r is null||string.IsNullOrEmpty(r.S("CustomerId"))){tx.Rollback();return Results.BadRequest(new{error="Hãy gắn khách hàng vào đơn trước."});}if(r.I("PointsRedeemed")>0){tx.Rollback();return Results.Conflict(new{error="Đơn này đã đổi điểm."});}var points=Math.Min(x.Points,r.I("Points"));var discount=Math.Min(points*1000,Math.Max(0,r.I("Subtotal")-r.I("Discount")));points=discount/1000;if(points<=0){tx.Rollback();return Results.BadRequest(new{error="Đơn không còn giá trị để đổi điểm."});}await DemoDb.Exec(c,tx,"UPDATE Customers SET Points=Points-@p WHERE Id=@c;UPDATE Orders SET PointsRedeemed=@p,LoyaltyDiscount=@d,Total=Subtotal-Discount-@d WHERE Id=@id",("@p",points),("@d",discount),("@c",r.S("CustomerId")),("@id",id));tx.Commit();return Results.Ok(new{points,discount,total=r.I("Subtotal")-r.I("Discount")-discount});});

        app.MapGet("/api/promotions",async()=>{await using var c=DemoDb.Open();var rs=await DemoDb.Rows(c,"SELECT Id,Code,Name,DiscountType,Value,MinimumOrder,MaximumDiscount,StartsAt,EndsAt,IsActive FROM Promotions ORDER BY CreatedAt DESC");return Results.Ok(rs.Select(r=>new{id=r.G("Id"),code=r.S("Code"),name=r.S("Name"),type=r.S("DiscountType"),value=r.I("Value"),minimumOrder=r.I("MinimumOrder"),maximumDiscount=r["MaximumDiscount"] is null?(int?)null:r.I("MaximumDiscount"),startsAt=r.DN("StartsAt"),endsAt=r.DN("EndsAt"),isActive=r.B("IsActive")}));});
        app.MapPost("/api/promotions",async(PromotionInput x,ClaimsPrincipal u)=>{if(!Has(u,"owner","manager"))return Results.Json(new{error="Không có quyền tạo khuyến mãi."},statusCode:403);if(!new[]{"percent","fixed"}.Contains(x.Type)||x.Value<=0)return Results.BadRequest(new{error="Khuyến mãi không hợp lệ."});await using var c=DemoDb.Open();var id=DemoDb.Id();try{await DemoDb.Exec(c,"INSERT INTO Promotions(Id,StoreId,Code,Name,DiscountType,Value,MinimumOrder,MaximumDiscount,StartsAt,EndsAt,CreatedAt)VALUES(@id,(SELECT Id FROM Stores LIMIT 1),@code,@n,@t,@v,@min,@max,@start,@end,@now)",( "@id",id),("@code",x.Code.Trim().ToUpperInvariant()),("@n",x.Name.Trim()),("@t",x.Type),("@v",x.Value),("@min",x.MinimumOrder),("@max",x.MaximumDiscount),("@start",x.StartsAt),("@end",x.EndsAt),("@now",DemoDb.Now));return Results.Ok(new{id=Guid.Parse(id)});}catch(SqliteException){return Results.Conflict(new{error="Mã khuyến mãi đã tồn tại."});}});
        app.MapPost("/api/orders/{id:guid}/promotion",async(Guid id,ApplyPromotionInput x)=>{await using var c=DemoDb.Open();var now=DemoDb.Now;var promo=(await DemoDb.Rows(c,"SELECT Id,DiscountType,Value,MinimumOrder,MaximumDiscount FROM Promotions WHERE Code=@code AND IsActive=1 AND (StartsAt IS NULL OR StartsAt<=@now) AND (EndsAt IS NULL OR EndsAt>=@now) LIMIT 1",("@code",x.Code.Trim().ToUpperInvariant()),("@now",now))).FirstOrDefault();if(promo is null)return Results.NotFound(new{error="Mã giảm giá không hợp lệ hoặc đã hết hạn."});var order=(await DemoDb.Rows(c,"SELECT Subtotal,LoyaltyDiscount FROM Orders WHERE Id=@id AND Status NOT IN ('paid','cancelled')",("@id",id))).FirstOrDefault();if(order is null)return Results.NotFound(new{error="Không tìm thấy đơn."});if(order.I("Subtotal")<promo.I("MinimumOrder"))return Results.BadRequest(new{error=$"Đơn tối thiểu {promo.I("MinimumOrder"):N0}đ."});var discount=promo.S("DiscountType")=="percent"?order.I("Subtotal")*promo.I("Value")/100:promo.I("Value");if(promo["MaximumDiscount"] is not null)discount=Math.Min(discount,promo.I("MaximumDiscount"));discount=Math.Min(discount,order.I("Subtotal")-order.I("LoyaltyDiscount"));await DemoDb.Exec(c,"UPDATE Orders SET PromotionId=@p,Discount=@d,Total=Subtotal-@d-LoyaltyDiscount WHERE Id=@id",("@p",promo.S("Id")),("@d",discount),("@id",id));return Results.Ok(new{id,discount,total=order.I("Subtotal")-discount-order.I("LoyaltyDiscount")});});

        app.MapGet("/api/shifts/current",async(ClaimsPrincipal u)=>{await using var c=DemoDb.Open();var r=(await DemoDb.Rows(c,ShiftSelect+" WHERE s.OpenedBy=@u AND s.Status='open' ORDER BY s.OpenedAt DESC LIMIT 1",("@u",U(u)),("@now",DemoDb.Now))).FirstOrDefault();return Results.Ok(r is null?null:ShiftObject(r));});
        app.MapPost("/api/shifts/open",async(OpenShiftInput x,ClaimsPrincipal u)=>{if(!Has(u,"owner","manager","cashier"))return Results.Json(new{error="Không có quyền mở ca."},statusCode:403);await using var c=DemoDb.Open();if(await DemoDb.ScalarLong(c,"SELECT COUNT(*) FROM WorkShifts WHERE OpenedBy=@u AND Status='open'",("@u",U(u)))>0)return Results.Conflict(new{error="Bạn đang có một ca chưa kết thúc."});var id=DemoDb.Id();var now=DemoDb.Now;await DemoDb.Exec(c,"INSERT INTO WorkShifts(Id,StoreId,OpenedBy,OpenedAt,OpeningCash)VALUES(@id,(SELECT Id FROM Stores LIMIT 1),@u,@now,@cash)",( "@id",id),("@u",U(u)),("@now",now),("@cash",x.OpeningCash));return Results.Ok(new{id=Guid.Parse(id),openedAt=DateTime.Parse(now)});});
        app.MapPost("/api/shifts/{id:guid}/close",async(Guid id,CloseShiftInput x,ClaimsPrincipal u)=>{if(!Has(u,"owner","manager","cashier"))return Results.Json(new{error="Không có quyền kết ca."},statusCode:403);await using var c=DemoDb.Open();var shift=(await DemoDb.Rows(c,"SELECT OpenedBy,OpenedAt,OpeningCash FROM WorkShifts WHERE Id=@id AND Status='open'",("@id",id))).FirstOrDefault();if(shift is null)return Results.NotFound(new{error="Ca không tồn tại hoặc đã đóng."});var sales=(await DemoDb.Rows(c,"SELECT COALESCE(SUM(CASE WHEN Method='cash' THEN Amount ELSE 0 END),0) Cash,COALESCE(SUM(CASE WHEN Method<>'cash' THEN Amount ELSE 0 END),0) NonCash,COUNT(*) Tx FROM Payments WHERE ReceivedBy=@u AND PaidAt>=@open",("@u",shift.S("OpenedBy")),("@open",shift.S("OpenedAt")))).First();var expected=shift.I("OpeningCash")+sales.I("Cash");var variance=x.ClosingCash-expected;await DemoDb.Exec(c,"UPDATE WorkShifts SET Status='closed',ClosedBy=@u,ClosedAt=@now,ClosingCash=@cash,ExpectedCash=@expected,Variance=@variance,Note=@note WHERE Id=@id",("@u",U(u)),("@now",DemoDb.Now),("@cash",x.ClosingCash),("@expected",expected),("@variance",variance),("@note",x.Note),("@id",id));return Results.Ok(new{expectedCash=expected,variance,cashSales=sales.I("Cash"),nonCashSales=sales.I("NonCash"),totalSales=sales.I("Cash")+sales.I("NonCash"),transactionCount=sales.I("Tx")});});
        app.MapGet("/api/shifts",async(ClaimsPrincipal u)=>{if(!Has(u,"owner","manager","cashier"))return Results.Json(new{error="Không có quyền xem lịch sử ca."},statusCode:403);await using var c=DemoDb.Open();var filter=R(u)=="cashier"?" WHERE s.OpenedBy=@u":"";var rs=await DemoDb.Rows(c,ShiftSelect+filter+" ORDER BY s.OpenedAt DESC LIMIT 100",("@u",U(u)),("@now",DemoDb.Now));return Results.Ok(rs.Select(ShiftObject));});
        app.MapGet("/api/reports/operations",async(ClaimsPrincipal u)=>{if(!Has(u,"owner","manager"))return Results.Json(new{error="Không có quyền xem báo cáo vận hành."},statusCode:403);await using var c=DemoDb.Open();var cancels=await DemoDb.Rows(c,"SELECT c.CreatedAt,o.OrderNumber,COALESCE(i.ProductName,'Toàn đơn') Item,c.Reason,c.Amount,COALESCE(u.FullName,'Hệ thống') Staff FROM OrderCancellations c JOIN Orders o ON o.Id=c.OrderId LEFT JOIN OrderItems i ON i.Id=c.OrderItemId LEFT JOIN Users u ON u.Id=c.CancelledBy ORDER BY c.CreatedAt DESC LIMIT 100");var staff=await DemoDb.Rows(c,"SELECT u.Id,u.FullName,u.Role,(SELECT COUNT(*) FROM Orders o WHERE o.OpenedBy=u.Id) Orders,(SELECT COUNT(*) FROM OrderItems i WHERE i.PreparedBy=u.Id) PreparedItems,(SELECT COALESCE(SUM(Amount),0) FROM Payments p WHERE p.ReceivedBy=u.Id) ReceivedAmount FROM Users u WHERE u.IsActive=1 ORDER BY u.FullName");return Results.Ok(new{cancellations=cancels.Select(r=>new{createdAt=r.D("CreatedAt"),orderNumber=r.L("OrderNumber"),item=r.S("Item"),reason=r.S("Reason"),amount=r.I("Amount"),staff=r.S("Staff")}),staffPerformance=staff.Select(r=>new{id=r.G("Id"),name=r.S("FullName"),role=r.S("Role"),orders=r.I("Orders"),preparedItems=r.I("PreparedItems"),receivedAmount=r.I("ReceivedAmount")})});});
    }
    const string ShiftSelect="""SELECT s.Id,u.FullName Staff,s.OpenedAt,s.ClosedAt,s.OpeningCash,s.ClosingCash,s.ExpectedCash,s.Variance,s.Status,COALESCE((SELECT SUM(Amount) FROM Payments p WHERE p.ReceivedBy=s.OpenedBy AND p.Method='cash' AND p.PaidAt>=s.OpenedAt AND p.PaidAt<=COALESCE(s.ClosedAt,@now)),0) CashSales,COALESCE((SELECT SUM(Amount) FROM Payments p WHERE p.ReceivedBy=s.OpenedBy AND p.Method<>'cash' AND p.PaidAt>=s.OpenedAt AND p.PaidAt<=COALESCE(s.ClosedAt,@now)),0) NonCashSales,(SELECT COUNT(*) FROM Payments p WHERE p.ReceivedBy=s.OpenedBy AND p.PaidAt>=s.OpenedAt AND p.PaidAt<=COALESCE(s.ClosedAt,@now)) TransactionCount FROM WorkShifts s JOIN Users u ON u.Id=s.OpenedBy""";
    static object ShiftObject(Dictionary<string,object?> r){var cash=r.I("CashSales");var non=r.I("NonCashSales");return new{id=r.G("Id"),staff=r.S("Staff"),openedAt=r.D("OpenedAt"),closedAt=r.DN("ClosedAt"),openingCash=r.I("OpeningCash"),closingCash=r["ClosingCash"] is null?(int?)null:r.I("ClosingCash"),expectedCash=r["ExpectedCash"] is null?r.I("OpeningCash")+cash:r.I("ExpectedCash"),variance=r["Variance"] is null?(int?)null:r.I("Variance"),status=r.S("Status"),cashSales=cash,nonCashSales=non,totalSales=cash+non,transactionCount=r.I("TransactionCount")};}
}

record ToppingInput(Guid ProductId,string Name,int Price);
record AreaInput(string Name,int CanvasWidth=1000,int CanvasHeight=600);
record TablePositionInput(int X,int Y);
record TableLayoutInput(Guid AreaId,int X,int Y,int Width,int Height,string Shape);
record TableTransferInput(Guid OrderId,Guid TargetTableId,bool Merge);
record CustomerInput(string Name,string Phone);
record OrderCustomerInput(Guid CustomerId);
record RedeemPointsInput(int Points);
record PromotionInput(string Code,string Name,string Type,int Value,int MinimumOrder,int? MaximumDiscount,DateTime? StartsAt,DateTime? EndsAt);
record ApplyPromotionInput(string Code);
record OpenShiftInput(int OpeningCash);
record CloseShiftInput(int ClosingCash,string? Note);
